#!/usr/bin/env node

/**
 * Update environment files with dynamic ports
 */

const fs = require('fs');
const path = require('path');

const serverPort = process.env.SERVER_PORT || '8787';
const webPort = process.env.WEB_PORT || '5173';
const dbPort = process.env.DB_PORT || '5432';
const proxyPort = process.env.PROXY_PORT || '4444';
const prNumber = process.env.PR_NUMBER;

// Generate web environment file
const webEnvContent = `# Auto-generated development environment variables
# Generated by scripts/update-env-files.js
VITE_API_URL=http://127.0.0.1:${serverPort}
#VITE_WS_URL=ws://127.0.0.1:${serverPort}/api/sync 

# V3 is now the default - no feature flags needed
`;

// Generate server environment file for local Neon setup
const serverEnvContent = `# Auto-generated server environment variables
# For PR #${prNumber || 'main'}
DATABASE_URL=http://db.localtest.me:${proxyPort}/sql
DIRECT_DATABASE_URL=postgres://postgres:postgres@localhost:${dbPort}/vibestack_pr_${prNumber || '0'}
SERVER_PORT=${serverPort}
WEB_PORT=${webPort}
DB_PORT=${dbPort}
PROXY_PORT=${proxyPort}
PR_NUMBER=${prNumber || '0'}
`;

// Write web env file
const webEnvPath = prNumber 
  ? path.join(__dirname, `../apps/web/.env.pr-${prNumber}`)
  : path.join(__dirname, '../apps/web/.env.development.generated');

fs.writeFileSync(webEnvPath, webEnvContent);
console.log(`   Generated web env at: ${webEnvPath}`);

// Write server env file if using local database
if (process.env.USE_LOCAL_DB === 'true') {
  const serverEnvPath = prNumber
    ? path.join(__dirname, `../apps/server/.env.pr-${prNumber}`)
    : path.join(__dirname, '../apps/server/.env.development.generated');
  
  fs.writeFileSync(serverEnvPath, serverEnvContent);
  console.log(`   Generated server env at: ${serverEnvPath}`);
}